from . import bip_config
from .tools import python_log
import os
import zipfile
import subprocess
from collections import defaultdict
from .bts_info import oam_session, get_oam_session
from taf.sbts.oam.coam.admin.exceptions import AdminApiProcedureFailureException
import logging


logger = logging.getLogger()


# container to keep all oam sessions
OAM_SESSIONS = {}


def get_admin_connection(gnb_id=0):
    return get_oam_session(gnb_id)


@python_log
def start(gnb_id=0):
    admin_connection = get_oam_session(gnb_id)
    try:
        start_interface_mirroring(admin_connection)
    except AdminApiProcedureFailureException:
        stop_interface_mirroring(admin_connection)
        start_interface_mirroring(admin_connection)

    # add session to container
    OAM_SESSIONS[gnb_id] = admin_connection


@python_log
def stop(gnb_id=0):
    stop_interface_mirroring(OAM_SESSIONS[gnb_id])
    OAM_SESSIONS[gnb_id].disconnect()


@python_log
def collect(gnb_id=0, target_dir="/tmp"):
    with oam_session(gnb_id) as admin_connection:
        bip_traces = collect_bip_trace(admin_connection, target_dir)
        return bip_traces


def read_snapshot_file_list(output_file_name):
    try:
        snapshot_zipped = zipfile.ZipFile(output_file_name)
    except zipfile.BadZipFile:
        raise AssertionError("Collected Log is not a zip file!")
    else:
        if 'snapshot_file_list.txt' in snapshot_zipped.namelist():
            return snapshot_zipped.open('snapshot_file_list.txt').read()
        else:
            raise AssertionError("No snapshot_file_list.txt found in file!")


@python_log
def get_snapshot_pcap_zip_files(output_file_name):
    file_list_content = read_snapshot_file_list(output_file_name)

    zip_files = defaultdict(list)
    for line in file_list_content.decode().split('\n'):
        if line.endswith('zip:'):
            current_zip = line.strip().strip(':')
        if line.startswith('    ') and current_zip:
            zip_files[current_zip].append(line.strip())

    def is_pcap_in_content(content):
        return [filename for filename in content if 'pcap' in filename]

    zips_with_pcap = [zip_file for zip_file, content in zip_files.items() if is_pcap_in_content(content)]
    return zips_with_pcap


def decompress_xz(xz_file):
    subprocess.Popen(['xz', '-d', xz_file]).communicate()
    return os.path.splitext(xz_file)[0]


def extract_xz_compressed_pcaps_from_zip(zip_file):
    """
    Extract the pcap.xz files contained in the given zip file
    """
    output_path, _ = os.path.split(os.path.realpath(zip_file))
    extracted_zip = zipfile.ZipFile(zip_file)
    xz_pcap_files = []
    for xz_pcap_filename in [name for name in extracted_zip.namelist() if 'pcap' in name]:
        xz_pcap_files.append(extracted_zip.extract(xz_pcap_filename, path=output_path))
    return xz_pcap_files


@python_log
def extract_pcaps(output_file_name):
    output_path, _ = os.path.split(os.path.realpath(output_file_name))

    pcap_files = []

    for zip_file in get_snapshot_pcap_zip_files(output_file_name):
        extracted_zip_filename = zipfile.ZipFile(output_file_name).extract(zip_file, path=output_path)
        xz_pcap_files = extract_xz_compressed_pcaps_from_zip(extracted_zip_filename)

        for xz_pcap_filename in xz_pcap_files:
            pcap_files.append(decompress_xz(xz_pcap_filename))

    return pcap_files


@python_log
def start_interface_mirroring(admin_connection):
    admin_mirroring_time = bip_config.BIP_CONFIG.get('admin_mirroring_time', 2147483647)
    admin_interface = bip_config.BIP_CONFIG.get('admin_interface', 'L1-L2')

    if admin_interface not in ['L1-L2', 'L2Hi-L2Lo']:
        logger.warn('Unsupported Interface {}, Using L1-L2'.format(admin_interface))
        admin_interface = 'L1-L2'

    admin_connection.interface_mirroring(operation='Start',
                                         interface=admin_interface,
                                         destination='Local',
                                         mirroring_time=admin_mirroring_time,
                                         timeout=30,
                                         detailed_output=True)


@python_log
def stop_interface_mirroring(admin_connection):
    admin_connection.interface_mirroring(operation='Stop',
                                         interface='L1-L2',
                                         destination='Local',
                                         timeout=30,
                                         detailed_output=True)


@python_log
def collect_bip_trace(admin_connection, target_dir='/tmp'):
    output_file_name = os.path.join(target_dir, 'admin_mirror_bip_trace.zip')
    admin_collect_timeout = bip_config.BIP_CONFIG.get('admin_collect_timeout', 600)
    admin_connection.collect_mirroring_logs(output_file_name,
                                            timeout=admin_collect_timeout,
                                            detailed_output=True)
    return extract_pcaps(output_file_name)
